        new AbortController().signal,
        () => {},
        { cwd: process.cwd() },
      );

      expect(editResult.isError).toBeFalsy();
      expect(readFileSync(filePath, "utf8")).toContain("export const x = 2;");
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });
