/**
 * Reproduction for #276 / #272: ast_search pattern correctness.
 * Uses the real bundled ast-grep binary (no child_process mock).
 */
import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { registerSgTool, isSgAvailable } from "../src/sg.js";

function getSgTool(): any {
  let captured: any = null;
  registerSgTool({ registerTool(def: any) { captured = def; } } as any);
  if (!captured) throw new Error("sg tool was not registered");
  return captured;
}

function text(result: any): string {
  return result.content?.find((c: any) => c.type === "text")?.text ?? "";
}

describe.skipIf(!isSgAvailable())("#276 ast_search pattern correctness", () => {
  let dir = "";
  let file = "";
  const tool = getSgTool();
  const run = (pattern: string, extra: Record<string, unknown> = {}) =>
    tool.execute("tc", { pattern, path: file, lang: "javascript", ...extra }, new AbortController().signal, () => {}, { cwd: dir });

  beforeAll(() => {
    dir = mkdtempSync(path.join(tmpdir(), "repro-276-sg-"));
    file = path.join(dir, "a.js");
    writeFileSync(file, "let i = 0;\n--i;\nconst y = 1;\nconst z = -y;\n", "utf8");
  });
  afterAll(() => rmSync(dir, { recursive: true, force: true }));

  it("pattern '--$A' finds the pre-decrement '--i' instead of being parsed as a CLI flag", async () => {
    const result = await run("--$A");
    expect(result.isError).toBeFalsy();
    expect(text(result)).toContain("--i;");
  });

  it("pattern '-$A' finds the negation '-y'", async () => {
    const result = await run("-$A");
    expect(result.isError).toBeFalsy();
    expect(text(result)).toContain("const z = -y;");
  });

  it("pattern '--help' is treated as a pattern, not a CLI flag", async () => {
    const result = await run("--help");
    expect(text(result)).not.toContain("a value is required for '--pattern");
  });

  it.each(["function (((", "foo("])("malformed pattern %j reports a parse failure, not 'No matches'", async (pattern) => {
    const result = await run(pattern);
    expect(result.isError).toBe(true);
    expect(text(result)).toMatch(/parse/i);
    expect(text(result)).not.toContain("No matches found");
  });

  it.each(["", "   "])("empty/whitespace pattern %j is rejected up front without ast-grep noise", async (pattern) => {
    const result = await run(pattern);
    expect(result.isError).toBe(true);
    expect(text(result)).not.toContain("postinstall");
    expect(text(result)).not.toContain("No matches found");
  });

  it("a valid pattern with no matches still reports 'No matches found'", async () => {
    const result = await run("nonexistentCall123($X)");
    expect(result.isError).toBeFalsy();
    expect(text(result)).toBe("No matches found for pattern: nonexistentCall123($X)");
  });

  it("surfaced ast-grep errors never contain the postinstall banner", async () => {
    const result = await run("$X", { lang: "klingon" });
    expect(result.isError).toBe(true);
    expect(text(result)).toContain("klingon");
    expect(text(result)).not.toContain("postinstall");
  });
});

import { describe, it, expect, vi, afterEach, beforeAll } from "vitest";
import * as cp from "node:child_process";
import { resolve, dirname, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { readFileSync } from "node:fs";
import { ensureHashInit, computeLineHash, escapeControlCharsForDisplay } from "../src/hashline.js";
import * as sgModule from "../src/sg.js";
import * as sgOutputModule from "../src/sg-output.js";

vi.mock("node:child_process", () => ({
  execFile: vi.fn(),
}));

const __dirname = dirname(fileURLToPath(import.meta.url));
const fixturesDir = resolve(__dirname, "fixtures");

async function getSgTool() {
  let captured: any = null;
  const mockPi = { registerTool(def: any) { captured = def; } };
  sgModule.registerSgTool(mockPi as any);
  if (!captured) throw new Error("sg tool was not registered");
  return captured;
}

function getTextContent(result: any): string {
  return result.content?.find((c: any) => c.type === "text")?.text ?? "";
}

describe("buildSgOutput", () => {
  beforeAll(async () => {
    await ensureHashInit();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("renders grouped ast_search matches through one shared builder", async () => {
    const spy = vi.spyOn(sgOutputModule, "buildSgOutput");
    const tool = await getSgTool();
    const filePath = resolve(fixturesDir, "small.ts");
    const displayPath = relative(process.cwd(), filePath);
    const sourceLines = readFileSync(filePath, "utf-8").replace(/\r\n/g, "\n").split("\n");

    vi.mocked(cp.execFile).mockImplementation((_cmd: any, _args: any, _opts: any, cb: any) => {
      cb(null, JSON.stringify([
        { file: filePath, range: { start: { line: 44, column: 0 }, end: { line: 44, column: 0 } } },
        { file: filePath, range: { start: { line: 45, column: 0 }, end: { line: 48, column: 0 } } },
      ]), "");
      return {} as any;
    });

    const result = await tool.execute(
      "tc",
      { pattern: "export function $NAME($$$PARAMS) { $$$BODY }", path: filePath },
      new AbortController().signal,
      () => {},
      { cwd: process.cwd() },
    );

    const built = spy.mock.results.at(-1)?.value;
    const expectedText = [
      `--- ${displayPath} ---`,
      ...[45, 46, 47, 48, 49].map((lineNumber) => {
        const raw = sourceLines[lineNumber - 1];
        const hash = computeLineHash(lineNumber, raw);
        return `>>${lineNumber}:${hash}|${escapeControlCharsForDisplay(raw)}`;
      }),
    ].join("\n");

    expect(built.text).toBe(expectedText);
    expect(built.ptcValue.tool).toBe("ast_search");
    expect(getTextContent(result)).toBe(built.text);
    expect(result.details?.ptcValue).toEqual(built.ptcValue);
  });

  it("projects no-match responses through the shared sg builder", async () => {
    expect(sgOutputModule.buildSgOutput({ pattern: "does-not-match", files: [] }).text).toBe(
      "No matches found for pattern: does-not-match",
    );

    const spy = vi.spyOn(sgOutputModule, "buildSgOutput");
    const tool = await getSgTool();
    vi.mocked(cp.execFile).mockImplementation((_cmd: any, _args: any, _opts: any, cb: any) => {
      cb(null, "[]", "");
      return {} as any;
    });

    const result = await tool.execute(
      "tc",
      { pattern: "does-not-match" },
      new AbortController().signal,
      () => {},
      { cwd: process.cwd() },
    );

    const built = spy.mock.results.at(-1)?.value;
    expect(built.ptcValue.tool).toBe("ast_search");
    expect(getTextContent(result)).toBe(built.text);
    expect(result.details?.ptcValue).toEqual(built.ptcValue);
  });
});

import { describe, expect, it, vi } from "vitest";
import * as cp from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { basename, join } from "node:path";
import { buildFileResource } from "../src/context-hygiene.js";
import { registerSgTool } from "../src/sg.js";

vi.mock("node:child_process", async (importOriginal) => ({
  ...(await importOriginal<typeof import("node:child_process")>()),
  execFile: vi.fn(),
}));

describe("ast_search truncated consumer parity", () => {
  it("retains admitted files for PTC, resources, and anchoring when blocks are hidden", async () => {
    const dir = mkdtempSync(join(tmpdir(), "pi-ast-consumers-"));
    const files = Array.from({ length: 3 }, (_, index) => join(dir, `file-${index}.ts`));
    files.forEach((file, index) => writeFileSync(file, `const value${index} = ${index};\n`, "utf8"));
    vi.mocked(cp.execFile).mockImplementation((_cmd: any, _args: any, _opts: any, callback: any) => {
      callback(null, JSON.stringify(files.map((file) => ({
        file,
        range: { start: { line: 0, column: 0 }, end: { line: 0, column: 10 } },
      }))), "");
      return {} as any;
    });

    const onFileAnchored = vi.fn();
    let tool: any;
    registerSgTool(
      { registerTool(def: any) { tool = def; } } as any,
      { outputBudget: { maxLines: 4, maxBytes: 4096 }, onFileAnchored },
    );
    const result = await tool.execute(
      "ast-consumers",
      { pattern: "$X", path: dir, limit: 3 },
      new AbortController().signal,
      () => {},
      { cwd: process.cwd() },
    );
    const visible = result.content[0].text;

    expect(result.details.ptcValue.files).toHaveLength(3);
    expect(result.details.ptcValue.truncation.outputBudget).toMatchObject({
      totalBlocks: 3,
      shownBlocks: 1,
      omittedBlocks: 2,
    });
    expect(result.details.contextHygiene.resources).toEqual(files.map(buildFileResource));
    for (const file of files) expect(onFileAnchored).toHaveBeenCalledWith(file);
    expect(visible).toContain(basename(files[0]));
    expect(visible).not.toContain(basename(files[1]));
    expect(visible).not.toContain(basename(files[2]));
    expect(visible.split("\n").length).toBeLessThanOrEqual(4);
  });
});

